const topTen = [
  "Furniture that will not fit the Oregon layout",
  "Unused exercise equipment",
  "Spare shelving and storage units",
  "Duplicate tools and lawn gear",
  "Rarely used small appliances",
  "Extra dishes and serving sets",
  "Books you will not reread",
  "Decor you would not put up again",
