const measure = document.createElement("canvas").getContext("2d");
function wrap(value, maxWidth, size) {
  measure.font = `${size}px Arial, sans-serif`;
  const lines = [];
  let line = "";
  for (const word of value.split(" ")) {
    const next = line ? line + " " + word : word;
    if (line && measure.measureText(next).width > maxWidth) {
      lines.push(line);
      line = word;
    } else {
      line = next;
    }
  }
  if (line) lines.push(line);
  return lines;
}

function makePDF(W, H) {
  const L = 44, R = W - 44, width = R - L;
  const pages = [];
  let ops = [];
  const n = v => Number(v.toFixed(2));
  const esc = s => s.replace(/[\\()]/g, c => "\\" + c);

  function text(x, y, value, size = 11, bold = false) {
    ops.push(`BT /${bold ? "F2" : "F1"} ${size} Tf 1 0 0 1 ${n(x)} ${n(H-y)} Tm (${esc(value)}) Tj ET`);
  }
  function rule(x1, y, x2) {
    ops.push(`0.55 w ${n(x1)} ${n(H-y)} m ${n(x2)} ${n(H-y)} l S`);
  }
  function rect(x, y, w, h, dashed = false) {
    ops.push(`q ${dashed ? "[3 3] 0 d 0.65 w" : "1 w"} ${n(x)} ${n(H-y-h)} ${n(w)} ${n(h)} re S Q`);
  }
  function header(title, sub) {
    text(L, 58, title, 23, true);
    text(L, 80, sub, 10.5);
    rule(L, 94, R);
  }
  function finish() {
    text(L, H - 33, "OHIO TO OREGON  |  JULY 16, 2026", 8.5, true);
    text(R - 38, H - 33, `${pages.length + 1} / 11`, 8.5);
    pages.push(ops.join("\n") + "\n");
    ops = [];
  }

  for (const [room, owner, time, tasks] of rooms) {
    header(room, `Owner: ${owner}  |  Estimated packing time: ${time}`);
    let y = 124;
    for (const [date, detail] of tasks) {
      rect(L, y - 9, 11, 11);
      text(L + 22, y, date, 10.5, true);
      y += 17;
      for (const row of wrap(detail, width - 32, 11.5)) {
        text(L + 22, y, row, 11.5);
        y += 15;
      }
      y += 12;
    }
    y += 12;
    text(L, y, "Notes / items still out", 10.5, true);
    for (let i = 1; i <= 3; i++) rule(L, y + i * 25, R);
    finish();
  }

  header("Box Labels", "Cut along dashed borders. Check either or both flags.");
  const top = 109, gap = 7;
  const labelH = (H - 55 - top - 5 * gap) / 6;

  for (let i = 0; i < 6; i++) {
    const y = top + i * (labelH + gap), x = L + 13, end = R - 13;
    rect(L, y, width, labelH, true);
    text(x, y + 19, "ROOM", 10, true);
    rule(x + 38, y + 21, end - 125);
    text(end - 111, y + 19, "BOX #", 10, true);
    rule(end - 74, y + 21, end);
    text(x, y + 39, "CONTENTS", 10, true);
    rule(x + 66, y + 41, end);
    rule(x, y + 58, end);
    rect(x, y + 69, 10, 10);
    text(x + 16, y + 78, "OPEN FIRST", 10, true);
    rect(x + 116, y + 69, 10, 10);
    text(x + 132, y + 78, "FRAGILE", 10, true);
  }
  finish();

  header("Top 10: Sell or Donate First",
         "Start with bulky items so there is time to arrange pickup.");
  topTen.forEach((item, i) => {
    const y = 124 + i * 29;
    rect(L, y - 9, 11, 11);
    text(L + 22, y, `${i + 1}.`, 11, true);
    text(L + 47, y, item, 11.5);
  });
  rule(L, 421, R);
  text(L, 444, "Set a one-week cutoff", 11, true);
  wrap("If it has not sold in a week, lower the price, offer it for free pickup, or donate it if accepted.", width - 10, 11.5)
    .forEach((row, i) => text(L, 464 + i * 15, row, 11.5));
  finish();

  // The PDF source is ASCII, so string lengths equal byte offsets.
  const objects = [null,
    "<< /Type /Catalog /Pages 2 0 R >>",
    "",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>"
  ];
  const kids = [];
  for (const stream of pages) {
    const pageID = objects.length;
    kids.push(`${pageID} 0 R`);
    objects.push(
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] ` +
      `/Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> ` +
      `/Contents ${pageID + 1} 0 R >>`,
      `<< /Length ${stream.length} >>\nstream\n${stream}endstream`
    );
  }
  objects[2] = `<< /Type /Pages /Count ${kids.length} /Kids [${kids.join(" ")}] >>`;

  let pdf = "%PDF-1.4\n";
  const offsets = [0];
  for (let i = 1; i < objects.length; i++) {
    offsets.push(pdf.length);
    pdf += `${i} 0 obj\n${objects[i]}\nendobj\n`;
  }
  const xref = pdf.length;
  pdf += `xref\n0 ${objects.length}\n0000000000 65535 f \n`;
  for (const offset of offsets.slice(1)) {
    pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return new Blob([pdf], {type: "application/pdf"});
}

function download(name, width, height) {
  const url = URL.createObjectURL(makePDF(width, height));
  const link = document.createElement("a");
  link.href = url;
  link.download = `Ohio-to-Oregon-Move-${name}.pdf`;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 30000);
}

document.getElementById("letter").onclick = () => download("Letter", 612, 792);
document.getElementById("a4").onclick = () => download("A4", 595.28, 841.89);
</script>
